SELECT

FROM SYS_COLUMN_HEADER
WHERE
LOGIC_DEL = 0

    AND COMPONENT_ID = #{dto.componentId}


    AND NAME = #{dto.name}


    AND DESCRIPTION = #{dto.description}


    AND HEIGHT = #{dto.height}


    AND MAX_HEIGHT = #{dto.maxHeight}


    AND INIT_PAGE_SIZE = #{dto.initPageSize}


    AND ENABLED = #{dto.enabled}


    AND RESIZE_FLAG = #{dto.resizeFlag}


    AND AUTO_COLS_WIDTH_FLAG = #{dto.autoColsWidthFlag}


    AND DEFAULT_TOOL_BAR_FLAG = #{dto.defaultToolBarFlag}

ORDER BY create_time DESC

